import { test, expect } from '@playwright/test';

test.describe('Prefers-reduced-motion Compliance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should respect user\'s prefers-reduced-motion setting and disable animations', async ({ page }) => {
    // Set up: Mock the user's prefers-reduced-motion setting
    await page.evaluate(() => {
      window.matchMedia('(prefers-reduced-motion: reduce)').matches = true;
    });

    // Verify the reduced motion setting is applied
    const reducedMotionSetting = page.getByRole('heading', { name: /preferences/i });
    await expect(reducedMotionSetting).toBeVisible();

    // Verify animations are disabled
    const animationContainer = page.locator('[data-testid="animation-container"]');
    await expect(animationContainer).toHaveClass(/disabled/i);

    // Verify content is still accessible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify interactive elements are still functional
    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();
    await button.click();

    // Verify no animations are triggered
    const animationLog = page.getByTestId('animation-log');
    await expect(animationLog).toContainText('No animations triggered');

    // Verify user feedback is clear
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();
  });

  test('should respect user\'s prefers-reduced-motion setting and disable animations when setting is not present', async ({ page }) => {
    // Set up: Mock the user's prefers-reduced-motion setting
    await page.evaluate(() => {
      window.matchMedia('(prefers-reduced-motion: reduce)').matches = false;
    });

    // Verify the reduced motion setting is not applied
    const reducedMotionSetting = page.getByRole('heading', { name: /preferences/i });
    await expect(reducedMotionSetting).toBeVisible();

    // Verify animations are enabled
    const animationContainer = page.locator('[data-testid="animation-container"]');
    await expect(animationContainer).toHaveClass(/enabled/i);

    // Verify content is still accessible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify interactive elements are still functional
    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();
    await button.click();

    // Verify animations are triggered
    const animationLog = page.getByTestId('animation-log');
    await expect(animationLog).toContainText('Animations triggered');

    // Verify user feedback is clear
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();
  });
});
